import { Super } from "./supabase";
export class Wallet extends Super {
    constructor(supabase, context) {
        super(supabase, context);
    }
    async getAddress(id) {
        const userWithWallet = await this.getUserFromWalletId(id);
        if (!userWithWallet)
            return null;
        return this._validateAndGetWalletAddress(userWithWallet);
    }
    async upsertWalletAddress(context, address) {
        const payload = context.payload;
        let userData = await this._checkIfUserExists(payload.sender.id);
        if (!userData) {
            userData = await this._registerNewUser(payload.sender);
        }
        const registeredWalletData = await this._getRegisteredWalletData(address);
        if (!registeredWalletData) {
            await this._registerNewWallet(context, {
                address,
                payload,
            });
        }
        else {
            await this._updateExistingWallet(context, {
                address,
                payload,
                walletData: registeredWalletData,
            });
        }
    }
    async unlinkWalletFromUserId(userId) {
        const userData = await this.getUserFromId(userId);
        if (!userData?.wallet_id) {
            throw this.context.logger.warn("The user does not have an associated wallet to unlink");
        }
        const { error } = await this.supabase.from("users").update({ wallet_id: null }).eq("id", userData.id);
        if (error) {
            throw this.context.logger.error(`Could not unlink the wallet.`, error);
        }
    }
    async getUserFromWalletId(id) {
        const { data, error } = await this.supabase.from("users").select("*, wallets(*)").filter("wallet_id", "eq", id).maybeSingle();
        if (error)
            throw this.context.logger.error(`Could not get the user from its wallet id.`, error);
        return data;
    }
    async getUserFromId(id) {
        const { data, error } = await this.supabase.from("users").select("*, wallets(*)").filter("id", "eq", id).maybeSingle();
        if (error)
            throw this.context.logger.error(`Could not get the user from its id.`, error);
        return data;
    }
    _validateAndGetWalletAddress(userWithWallet) {
        if (userWithWallet?.wallets?.address === undefined)
            throw this.context.logger.error("The wallet address is undefined");
        if (userWithWallet?.wallets?.address === null)
            throw this.context.logger.error("The wallet address is null");
        return userWithWallet?.wallets?.address;
    }
    async _checkIfUserExists(userId) {
        const { data, error } = await this.supabase.from("users").select("*").eq("id", userId).maybeSingle();
        if (error)
            throw this.context.logger.error(`Could not check if the user exists.`, error);
        return data;
    }
    async _registerNewUser(user) {
        const { data: userData, error: userError } = await this.supabase
            .from("users")
            .insert([{ id: user.id }])
            .select()
            .single();
        if (userError) {
            throw this.context.logger.error(`A new user could not be registered.`, userError);
        }
        return userData;
    }
    async checkIfWalletExists(wallet) {
        if (wallet === null) {
            return { data: null, error: null };
        }
        if (typeof wallet === "number") {
            return this.supabase.from("wallets").select("*").eq("id", wallet).maybeSingle();
        }
        else {
            return this.supabase.from("wallets").select("*").eq("address", wallet).maybeSingle();
        }
    }
    async _updateWalletId(walletId, userId) {
        const { error } = await this.supabase.from("users").update({ wallet_id: walletId }).eq("id", userId);
        if (error) {
            throw this.context.logger.error(`Could not update the wallet.`, error);
        }
    }
    async _getRegisteredWalletData(address) {
        const walletResponse = await this.checkIfWalletExists(address);
        const walletData = walletResponse.data;
        const walletError = walletResponse.error;
        if (walletError)
            throw this.context.logger.error(`Could not get the registered wallet.`, walletError);
        return walletData;
    }
    async _registerNewWallet(context, { address, payload }) {
        context.logger.info(`Registering a new wallet for the user ${payload.sender.id}: ${address}`);
        const walletData = await this._insertNewWallet(address);
        await this._updateWalletId(walletData.id, payload.sender.id);
    }
    async _updateExistingWallet(context, { walletData, payload }) {
        context.logger.info(`Updating a new wallet for the user ${payload.sender.id}: ${walletData.address}`);
        const existingLinkToUserWallet = await this.getUserFromWalletId(walletData.id);
        if (existingLinkToUserWallet && existingLinkToUserWallet.id !== context.payload.sender.id) {
            throw this.context.logger.warn(`Failed to register wallet because it is already associated with another user.`, existingLinkToUserWallet);
        }
        await this._updateWalletId(walletData.id, payload.sender.id);
    }
    async _insertNewWallet(address) {
        const newWallet = {
            address: address,
        };
        const { data: walletInsertData, error: walletInsertError } = await this.supabase.from("wallets").insert(newWallet).select().single();
        if (walletInsertError)
            throw this.context.logger.error(`Could not insert the new wallet.`, walletInsertError);
        return walletInsertData;
    }
}
